'use client'

/**
 * Rating quiz — working prototype. Builds a taste profile for people without
 * (much) Letterboxd history.
 *
 * Real: TMDB films + posters, the backend's MiniLM embeddings, adaptive
 * picking (lib/quiz/engine.ts), the backend's taste-vector maths, match scores
 * against the real users in the local DB.
 * Not yet: nothing is saved; favourites only search the quiz pool.
 *
 * Data comes from /quiz/films.json and /quiz/people.local.json, generated by
 * `go run ./cmd/quizseed` in services/api.
 *
 * Keys while rating: → loved, ← nope, ↑ fine, ↓ haven't seen, Z undo, D maths.
 */

import { useCallback, useEffect, useMemo, useState } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import { Heart, Meh, RotateCcw, ThumbsDown, EyeOff, Search, Check, Sigma } from 'lucide-react'
import { PhoneShell } from '../../components/layout/PhoneShell'
import { Button } from '../../components/ui/Button'
import { RuleDouble } from '../../components/ui/Dividers'
import { QuizCard } from '../../components/features/QuizCard'
import {
  type Answer,
  type Model,
  type Person,
  type Pool,
  type QuizState,
  type SeedFilm,
  MIN_RATED,
  TARGET_CONFIDENCE,
  buildPool,
  explain,
  fitModel,
  genreAffinity,
  isDone,
  matchPeople,
  posterUrl,
  ratedCount,
  strengthLabel,
  tasteVector,
  toImportPayload,
} from '../../lib/quiz/engine'

type Step = 'intro' | 'favourites' | 'rate' | 'result'
const EMPTY: QuizState = { favourites: [], responses: [] }

export default function QuizPage() {
  const [pool, setPool] = useState<Pool | null>(null)
  const [people, setPeople] = useState<Person[]>([])
  const [loadError, setLoadError] = useState<string | null>(null)
  const [step, setStep] = useState<Step>('intro')
  const [state, setState] = useState<QuizState>(EMPTY)

  useEffect(() => {
    fetch('/quiz/films.json')
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`films.json: HTTP ${r.status}`))))
      .then((seed: SeedFilm[]) => setPool(buildPool(seed)))
      .catch((e) => setLoadError(String(e)))
    fetch('/quiz/people.local.json')
      .then((r) => (r.ok ? r.json() : []))
      .then(setPeople)
      .catch(() => setPeople([]))
  }, [])

  const restart = () => {
    setState(EMPTY)
    setStep('intro')
  }

  return (
    <PhoneShell>
      <div className="flex flex-col flex-1 px-6 pt-8 pb-8">
        {loadError ? (
          <div className="font-sans text-sm flex flex-col gap-2">
            <p className="font-semibold">Couldn&apos;t load the film pool.</p>
            <p style={{ opacity: 0.6 }}>
              Generate it with <code className="font-mono">go run ./cmd/quizseed</code> in services/api. ({loadError})
            </p>
          </div>
        ) : !pool ? (
          <p className="font-sans text-sm m-auto" style={{ opacity: 0.5 }}>
            Loading films…
          </p>
        ) : (
          <>
            {step === 'intro' && <Intro count={pool.films.length} onStart={() => setStep('favourites')} />}
            {step === 'favourites' && (
              <Favourites
                pool={pool}
                selected={state.favourites}
                onChange={(favourites) => setState((s) => ({ ...s, favourites }))}
                onNext={() => setStep('rate')}
              />
            )}
            {step === 'rate' && <Rate pool={pool} state={state} setState={setState} onDone={() => setStep('result')} />}
            {step === 'result' && (
              <Result pool={pool} people={people} state={state} onRestart={restart} onMore={() => setStep('rate')} />
            )}
          </>
        )}
      </div>
    </PhoneShell>
  )
}

/* ── Shared ─────────────────────────────────────────────────────────────── */

function Header({ kicker, title, sub }: { kicker: string; title: string; sub?: string }) {
  return (
    <div className="flex flex-col gap-3">
      <RuleDouble />
      <p className="chapter-kicker">{kicker}</p>
      <h1 className="font-serif italic text-4xl leading-none" style={{ color: 'var(--ink-deep)' }}>
        {title}
      </h1>
      {sub && (
        <p className="font-sans text-sm" style={{ opacity: 0.6 }}>
          {sub}
        </p>
      )}
      <RuleDouble />
    </div>
  )
}

function StrengthBar({ confidence }: { confidence: number }) {
  return (
    <div className="flex items-center gap-3">
      <div className="flex-1 h-2 rounded-full overflow-hidden" style={{ background: 'var(--cream-2)' }}>
        <motion.div
          className="h-full rounded-full"
          style={{ background: 'var(--coral)' }}
          animate={{ width: `${Math.round(Math.min(1, confidence / TARGET_CONFIDENCE) * 100)}%` }}
          transition={{ duration: 0.4 }}
        />
      </div>
      <span className="font-sans text-xs font-semibold w-16 text-right" style={{ color: 'var(--coral-deep)' }}>
        {strengthLabel(confidence)}
      </span>
    </div>
  )
}

/* ── Intro ──────────────────────────────────────────────────────────────── */

function Intro({ count, onStart }: { count: number; onStart: () => void }) {
  return (
    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="flex flex-col flex-1 gap-8">
      <Header kicker="No Letterboxd? No problem" title="The Screen Test" sub="A minute or two. No wrong answers." />
      <ol className="flex flex-col gap-4 font-sans text-sm">
        {[
          ['Pick four favourites', 'The films that say the most about you.'],
          ['Swipe through the rest', 'Each film is picked from your previous answers to learn the most about you.'],
          ['Meet your matches', 'See who in Framed shares your taste.'],
        ].map(([t, d], i) => (
          <li key={t} className="flex gap-4">
            <span className="font-serif italic text-3xl leading-none" style={{ color: 'var(--coral)' }}>
              {i + 1}
            </span>
            <div>
              <p className="font-semibold" style={{ color: 'var(--ink-deep)' }}>
                {t}
              </p>
              <p style={{ opacity: 0.6 }}>{d}</p>
            </div>
          </li>
        ))}
      </ol>
      <p className="font-mono text-[10px]" style={{ opacity: 0.4 }}>
        {count} films in the pool
      </p>
      <div className="mt-auto">
        <Button onClick={onStart}>Start</Button>
      </div>
    </motion.div>
  )
}

/* ── Favourites ─────────────────────────────────────────────────────────── */

function Favourites({
  pool,
  selected,
  onChange,
  onNext,
}: {
  pool: Pool
  selected: number[]
  onChange: (ids: number[]) => void
  onNext: () => void
}) {
  const [query, setQuery] = useState('')
  const films = useMemo(() => {
    const q = query.trim().toLowerCase()
    const list = q
      ? pool.films.filter((f) => f.title.toLowerCase().includes(q) || f.directors.some((d) => d.toLowerCase().includes(q)))
      : [...pool.films].sort((a, b) => b.voteCount - a.voteCount)
    return list.slice(0, 60)
  }, [query, pool])

  const toggle = (id: number) => {
    if (selected.includes(id)) onChange(selected.filter((x) => x !== id))
    else if (selected.length < 4) onChange([...selected, id])
  }

  return (
    <div className="flex flex-col gap-4 h-[calc(100svh-4rem)] min-h-0">
      <Header kicker="Step 1 of 2" title="Four Favourites" sub="Pick up to four. You can skip this." />

      <div className="grid grid-cols-4 gap-2">
        {[0, 1, 2, 3].map((i) => {
          const film = selected[i] ? pool.byId.get(selected[i]) : undefined
          return (
            <button
              key={i}
              onClick={() => film && toggle(film.tmdbId)}
              className="rounded-lg overflow-hidden"
              style={{ aspectRatio: '2/3', border: film ? 'none' : '1.5px dashed rgba(74,27,12,0.25)' }}
              aria-label={film ? `Remove ${film.title}` : `Empty slot ${i + 1}`}
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              {film && <img src={posterUrl(film.posterPath, 'w185')} alt={film.title} className="w-full h-full object-cover" />}
            </button>
          )
        })}
      </div>

      <label className="flex items-center gap-2 rounded-full px-4 py-3" style={{ background: 'var(--cream-2)' }}>
        <Search size={16} style={{ opacity: 0.5 }} />
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search films or directors"
          className="bg-transparent outline-none flex-1 font-sans text-sm"
        />
      </label>

      <div className="flex-1 min-h-0 overflow-y-auto -mx-1 px-1 py-1">
        <div className="grid grid-cols-3 gap-2">
        {films.map((f) => {
          const isOn = selected.includes(f.tmdbId)
          return (
            <button
              key={f.tmdbId}
              onClick={() => toggle(f.tmdbId)}
              disabled={!isOn && selected.length >= 4}
              className="relative rounded-lg overflow-hidden transition-opacity disabled:opacity-40"
              style={{ aspectRatio: '2/3', outline: isOn ? '3px solid var(--coral)' : 'none', outlineOffset: 2 }}
              title={`${f.title} (${f.year})`}
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={posterUrl(f.posterPath, 'w185')} alt={f.title} loading="lazy" className="w-full h-full object-cover" />
              {isOn && (
                <span className="absolute top-1.5 right-1.5 rounded-full p-0.5" style={{ background: 'var(--coral)' }}>
                  <Check size={12} color="white" />
                </span>
              )}
            </button>
          )
        })}
        {films.length === 0 && (
          <p className="col-span-3 text-center font-sans text-sm py-6" style={{ opacity: 0.5 }}>
            Not in the quiz pool yet. The real version will search all of TMDB.
          </p>
        )}
        </div>
      </div>

      <div className="pt-1">
        <Button onClick={onNext}>{selected.length ? `Continue with ${selected.length}` : 'Skip'}</Button>
      </div>
    </div>
  )
}

/* ── Rate ───────────────────────────────────────────────────────────────── */

function Rate({
  pool,
  state,
  setState,
  onDone,
}: {
  pool: Pool
  state: QuizState
  setState: React.Dispatch<React.SetStateAction<QuizState>>
  onDone: () => void
}) {
  const model = useMemo(() => fitModel(pool, state), [pool, state])
  const current = model.predictions[0]
  const reason = current ? explain(model, current) : ''
  const rated = ratedCount(state)
  const [exitDir, setExitDir] = useState<'left' | 'right' | 'up' | 'down'>('right')
  const [showMaths, setShowMaths] = useState(false)

  const answer = useCallback(
    (a: Answer) => {
      if (!current) return
      setExitDir(a === 'loved' ? 'right' : a === 'nope' ? 'left' : a === 'fine' ? 'up' : 'down')
      const next = {
        ...state,
        responses: [...state.responses, { id: current.film.tmdbId, answer: a, followUp: !!current.followUpOf }],
      }
      setState(next)
      if (isDone(fitModel(pool, next), next)) setTimeout(onDone, 250)
    },
    [current, state, setState, onDone, pool],
  )

  const undo = useCallback(() => setState((s) => ({ ...s, responses: s.responses.slice(0, -1) })), [setState])

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const map: Record<string, Answer> = { ArrowRight: 'loved', ArrowLeft: 'nope', ArrowUp: 'fine', ArrowDown: 'unseen' }
      if (map[e.key]) {
        e.preventDefault()
        answer(map[e.key])
      } else if (e.key === 'z' || e.key === 'Backspace') undo()
      else if (e.key === 'd') setShowMaths((v) => !v)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [answer, undo])

  const exit = {
    right: { x: 400, rotate: 15, opacity: 0 },
    left: { x: -400, rotate: -15, opacity: 0 },
    up: { y: -400, opacity: 0 },
    down: { y: 300, opacity: 0, scale: 0.9 },
  }[exitDir]

  return (
    <div className="flex flex-col flex-1 gap-4">
      <div className="flex flex-col gap-2">
        <div className="flex items-baseline justify-between font-sans">
          <p className="chapter-kicker">Step 2 of 2</p>
          <p className="text-xs tabular-nums" style={{ opacity: 0.6 }}>
            {rated} rated · {state.responses.length - rated} skipped
          </p>
        </div>
        <StrengthBar confidence={model.confidence} />
      </div>

      <div className="relative flex-1 min-h-[420px]">
        <div className="absolute inset-x-4 inset-y-0 top-3 rounded-3xl" style={{ background: 'var(--cream-2)' }} />
        <AnimatePresence>
          {current && (
            <motion.div
              key={current.film.tmdbId}
              className="absolute inset-0"
              initial={{ scale: 0.95, opacity: 0, y: 10 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={exit}
              transition={{ duration: 0.25 }}
            >
              <QuizCard
                film={current.film}
                reason={reason}
                onSwipe={(d) => answer(d === 'right' ? 'loved' : d === 'left' ? 'nope' : 'fine')}
              />
            </motion.div>
          )}
        </AnimatePresence>
        {/* Preload the likely next posters */}
        <div className="hidden" aria-hidden>
          {model.predictions.slice(1, 4).map((p) => (
            // eslint-disable-next-line @next/next/no-img-element
            <img key={p.film.tmdbId} src={posterUrl(p.film.posterPath)} alt="" />
          ))}
        </div>
      </div>

      {showMaths && current && <Maths model={model} />}

      <div className="grid grid-cols-3 gap-3">
        <AnswerButton icon={<ThumbsDown size={22} />} label="Not for me" onClick={() => answer('nope')} bg="var(--ink-deep)" />
        <AnswerButton icon={<Meh size={22} />} label="It's fine" onClick={() => answer('fine')} bg="var(--amber)" fg="var(--ink-deep)" />
        <AnswerButton icon={<Heart size={22} />} label="Loved it" onClick={() => answer('loved')} bg="var(--teal)" />
      </div>
      <div className="flex items-center justify-between font-sans text-sm">
        <button onClick={undo} disabled={!state.responses.length} className="flex items-center gap-1.5 disabled:opacity-30" style={{ opacity: 0.7 }}>
          <RotateCcw size={14} /> Undo
        </button>
        <button onClick={() => answer('unseen')} className="flex items-center gap-1.5 font-semibold" style={{ color: 'var(--coral)' }}>
          <EyeOff size={14} /> Haven&apos;t seen it
        </button>
        <button onClick={onDone} disabled={rated < MIN_RATED} className="disabled:opacity-30" style={{ opacity: 0.7 }}>
          Finish
        </button>
      </div>
      <div className="flex items-center justify-center gap-3">
        <p className="hidden md:block font-mono text-[10px]" style={{ opacity: 0.4 }}>
          ← nope · ↑ fine · → loved · ↓ haven&apos;t seen · Z undo
        </p>
        <button onClick={() => setShowMaths((v) => !v)} className="flex items-center gap-1 font-mono text-[10px]" style={{ color: 'var(--coral)' }}>
          <Sigma size={12} /> {showMaths ? 'hide' : 'show'} maths
        </button>
      </div>
    </div>
  )
}

/** Debug panel: why the engine picked this card, and what came close. */
function Maths({ model }: { model: Model }) {
  const pct = (x: number) => `${Math.round(x * 100)}%`
  return (
    <div className="rounded-xl p-3 font-mono text-[10px] leading-relaxed" style={{ background: 'var(--ink-deep)', color: 'var(--cream)' }}>
      <p className="opacity-60 mb-1">
        confidence {pct(model.confidence)}/{pct(TARGET_CONFIDENCE)} · {model.obs.length} answers · score = P(seen) × (unsure + new lang)
      </p>
      <table className="w-full">
        <thead className="opacity-60">
          <tr>
            <th className="text-left font-normal">film</th>
            <th className="text-right font-normal">P(like)</th>
            <th className="text-right font-normal">unsure</th>
            <th className="text-right font-normal">new</th>
            <th className="text-right font-normal">P(seen)</th>
            <th className="text-right font-normal">score</th>
          </tr>
        </thead>
        <tbody>
          {model.predictions.slice(0, 5).map((p, i) => (
            <tr key={p.film.tmdbId} style={{ opacity: i === 0 ? 1 : 0.65 }}>
              <td className="truncate max-w-[130px]">
                {i === 0 ? '▸ ' : '  '}
                {p.film.title}
              </td>
              <td className="text-right">{pct(p.pLike)}</td>
              <td className="text-right">{pct(p.uncertainty)}</td>
              <td className="text-right">{p.novel ? '+' : ''}</td>
              <td className="text-right">{pct(p.pSeen)}</td>
              <td className="text-right">{p.score.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function AnswerButton({ icon, label, onClick, bg, fg = 'white' }: { icon: React.ReactNode; label: string; onClick: () => void; bg: string; fg?: string }) {
  return (
    <motion.button
      whileTap={{ scale: 0.94 }}
      onClick={onClick}
      className="flex flex-col items-center gap-1 rounded-2xl py-3 font-sans text-xs font-semibold"
      style={{ background: bg, color: fg }}
    >
      {icon}
      {label}
    </motion.button>
  )
}

/* ── Result ─────────────────────────────────────────────────────────────── */

function Result({
  pool,
  people,
  state,
  onRestart,
  onMore,
}: {
  pool: Pool
  people: Person[]
  state: QuizState
  onRestart: () => void
  onMore: () => void
}) {
  const model = useMemo(() => fitModel(pool, state), [pool, state])
  const vec = useMemo(() => tasteVector(pool, state), [pool, state])
  const matches = useMemo(() => (vec ? matchPeople(vec, people) : []), [vec, people])
  const genres = useMemo(() => genreAffinity(model), [model])
  const rated = ratedCount(state)
  const [showPayload, setShowPayload] = useState(false)

  const byLike = [...model.predictions].sort((a, b) => b.mean - a.mean)
  const picks = byLike.slice(0, 6)
  const skips = byLike.filter((p) => p.pSeen > 0.3).slice(-3).reverse()
  const label = strengthLabel(model.confidence)
  const fuzzy = rated < 25 // see notes: match % is unstable below ~25 films

  return (
    <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="flex flex-col flex-1 gap-6">
      <Header
        kicker="Your profile"
        title={label === 'Portrait' ? 'A clear picture' : label === 'Outline' ? 'Taking shape' : 'A first sketch'}
        sub={`${state.favourites.length} favourites · ${rated} ratings · ${state.responses.length - rated} skipped`}
      />
      <StrengthBar confidence={model.confidence} />

      {/* Matches */}
      <section className="flex flex-col gap-2">
        <p className="chapter-kicker">Closest in Framed</p>
        {matches.length === 0 && (
          <p className="font-sans text-xs" style={{ opacity: 0.5 }}>
            No people exported. Run quizseed with DATABASE_URL set.
          </p>
        )}
        {matches.map((m) => (
          <div key={m.person.handle} className="flex items-center gap-3 rounded-xl px-4 py-3" style={{ background: 'var(--cream-2)' }}>
            <div className="flex-1 min-w-0">
              <p className="font-sans text-sm font-semibold truncate" style={{ color: 'var(--ink-deep)' }}>
                @{m.person.handle}
              </p>
              <p className="font-sans text-[11px] truncate" style={{ opacity: 0.55 }}>
                {m.person.films} films · {m.person.topGenres.slice(0, 3).join(', ')}
              </p>
            </div>
            <div className="text-right">
              <p className="font-serif italic text-2xl leading-none" style={{ color: 'var(--coral)' }}>
                {fuzzy ? matchWord(m.score) : `${Math.round(m.score * 100)}%`}
              </p>
              <p className="font-mono text-[9px]" style={{ opacity: 0.4 }}>
                {fuzzy ? `${Math.round(m.score * 100)}% · rough` : `cos ${m.cosine.toFixed(3)}`}
              </p>
            </div>
          </div>
        ))}
      </section>

      {/* Predictions */}
      <section className="flex flex-col gap-2">
        <p className="chapter-kicker">We think you&apos;d love</p>
        <div className="grid grid-cols-3 gap-2">
          {picks.map((p) => (
            <div key={p.film.tmdbId} className="flex flex-col gap-1">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={posterUrl(p.film.posterPath, 'w185')} alt={p.film.title} className="rounded-lg w-full object-cover" style={{ aspectRatio: '2/3' }} />
              <p className="font-sans text-[10px] leading-tight truncate" style={{ opacity: 0.7 }}>
                {p.film.title}
              </p>
            </div>
          ))}
        </div>
        {skips.length > 0 && (
          <p className="font-sans text-xs pt-1" style={{ opacity: 0.6 }}>
            <span className="font-semibold">Probably skip:</span> {skips.map((p) => p.film.title).join(', ')}
          </p>
        )}
      </section>

      {/* Genres */}
      <section className="flex flex-col gap-2.5">
        <p className="chapter-kicker">By genre</p>
        {genres.map((g) => (
          <div key={g.genre} className="grid grid-cols-[110px_1fr_24px] items-center gap-3 font-sans text-xs">
            <span style={{ color: 'var(--ink-deep)' }}>{g.genre}</span>
            <div className="relative h-2 rounded-full" style={{ background: 'var(--cream-2)' }}>
              <div className="absolute left-1/2 top-[-3px] bottom-[-3px] w-px" style={{ background: 'var(--ink)', opacity: 0.25 }} />
              <motion.div
                className="absolute top-0 bottom-0 rounded-full"
                style={{
                  background: g.affinity >= 0 ? 'var(--teal)' : 'var(--coral)',
                  left: g.affinity >= 0 ? '50%' : undefined,
                  right: g.affinity < 0 ? '50%' : undefined,
                }}
                initial={{ width: 0 }}
                animate={{ width: `${Math.abs(g.affinity) * 50}%` }}
                transition={{ duration: 0.5 }}
              />
            </div>
            <span className="tabular-nums text-right" style={{ opacity: 0.4 }} title="films rated in this genre">
              {g.evidence}
            </span>
          </div>
        ))}
      </section>

      <button onClick={() => setShowPayload((v) => !v)} className="font-mono text-xs text-left" style={{ color: 'var(--coral)' }}>
        {showPayload ? '▾' : '▸'} What the backend would receive
      </button>
      {showPayload && (
        <pre className="font-mono text-[10px] rounded-xl p-3 overflow-x-auto max-h-60" style={{ background: 'var(--ink-deep)', color: 'var(--cream)' }}>
          {JSON.stringify(toImportPayload(pool, state), null, 2)}
        </pre>
      )}

      <div className="mt-auto flex flex-col gap-3">
        <Button onClick={onMore}>Rate more to sharpen it</Button>
        <Button variant="ghost" onClick={onRestart}>
          Start over
        </Button>
      </div>
      <p className="font-sans text-[9px] text-center" style={{ opacity: 0.4 }}>
        Film data and posters from TMDB. This product uses the TMDB API but is not endorsed or certified by TMDB.
      </p>
    </motion.div>
  )
}

function matchWord(score: number) {
  if (score >= 0.7) return 'Strong'
  if (score >= 0.45) return 'Good'
  if (score >= 0.2) return 'Some'
  return 'Little'
}
